/// Get the AI output
let raw = $json.output;

// Make sure output exists
if (!raw) {
  throw new Error("Final Bug Report Agent returned no output.");
}

// Convert to string
raw = String(raw).trim();

// Remove Markdown code fences if the AI returned ```json ... ```
raw = raw
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let report;

// Try to parse JSON
try {
  report = JSON.parse(raw);
} catch (error) {
  // Try to extract the JSON object if extra text was returned
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error(
      "Final Bug Report Agent did not return valid JSON.\n\nOutput:\n" + raw
    );
  }

  const jsonText = raw.substring(start, end + 1);

  try {
    report = JSON.parse(jsonText);
  } catch (secondError) {
    throw new Error(
      "Unable to parse Final Bug Report Agent output as JSON.\n\nOutput:\n" +
      raw
    );
  }
}

// Return clean structured JSON
return [
  {
    json: report
  }
];
